const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>Number.isFinite(x)?new Intl.NumberFormat('en-GB',{maximumFractionDigits:2,minimumFractionDigits:1}).format(x):'Not reported';
const period=(s,o)=>!o?'Not reported':s.frequency==='A'?o.date.slice(0,4):s.frequency==='M'?o.date.slice(0,7):s.frequency==='Q'?o.date.slice(0,4)+' Q'+(Math.floor((Number(o.date.slice(5,7))-1)/3)+1):o.date;
const cadence={A:'Annual',Q:'Quarterly',M:'Monthly',W:'Weekly',D:'Daily',E:'Decision dates'};
const sourceLink=(url,label='Original source')=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
let cached=null,pending=null;
export async function readMacroContext(force=false){
 if(!force&&cached&&Date.now()-cached.time<300000)return cached.feed;if(pending)return pending;
 pending=(async()=>{const r=await fetch(new URL('./data/macro-context.json',import.meta.url),{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('Public macro context unavailable.');const text=await r.text();if(text.length>6000000)throw Error('Macro context exceeds the public-data limit.');const feed=cached?.text===text?cached.feed:validateMacroContext(JSON.parse(text));cached={feed,time:Date.now(),text};return feed;})();try{return await pending;}finally{pending=null;}
}
export function contextChart(series,rows,{width=760,title=CONTEXT_SERIES[series?.id]?.title,unit=CONTEXT_SERIES[series?.id]?.unit,bars=false,frequency=series?.frequency||'D',exact=true}={}){
 return nativeMacroChart(rows,{width,title,unit,bars,frequency,exact});
}

function exactRows(rows,unit,annual=false){return `<details class="context-exact"><summary>Exact observations</summary><div class="table-wrap" tabindex="0" role="region" aria-label="Macro context exact observations"><table><thead><tr><th scope="col">Observation period</th><th scope="col">${esc(unit)}</th><th scope="col">Source status</th></tr></thead><tbody>${rows.map(o=>`<tr><th scope="row">${annual?o.date.slice(0,4):o.date}</th><td>${Number.isFinite(o.value)?esc(String(o.value)):'Not reported'}</td><td>${esc(o.status||'As published')}</td></tr>`).join('')}</tbody></table></div></details>`;}
export function macroIndicatorEntries({feed,releases,legacy,extended,country}){
 const entries=[];
 for(const [metric,title]of [['gdp','Real GDP growth'],['inflation','Consumer price inflation']]){
  const items=releaseCandidates(releases,legacy,country,metric,extended),current=items.find(s=>s.latest),history=releaseHistory(items);
  if(current)entries.push({id:metric,group:'Growth and prices',title,unit:'% YoY',frequency:current.spec.frequency,latest:current.latest,readingObservations:current.observations,source:current.spec.source,sourceUrl:current.latest.sourceUrl||current.spec.sourceUrl,retrievedAt:current.retrievedAt,method:current.spec.method,observations:history?.observations||[],historyTitle:history?.spec.title,historySource:history?.spec.source,historyFrequency:history?.spec.frequency,historyId:history?.id,historyRetrievedAt:history?.retrievedAt,sourceId:current.id,flags:[current.latest.status==='estimate'?'Estimate':current.latest.status==='provisional'?'Provisional':null,releaseSummary(current).outdated?'Older observation or acquisition':null,releaseSummary(current).laterMissing?'Later supplied period not reported':null].filter(Boolean)});
 }
 for(const [metric,title]of [['policy','Policy instrument rate'],['yield','Government bond yield']]){
  const item=rateCandidates(extended,feed,country,metric).find(s=>s.latest);if(item)entries.push({id:metric,group:'Policy and yields',title,unit:item.spec.unit,frequency:item.spec.frequency,latest:item.latest,source:item.spec.source,sourceUrl:item.spec.sourceUrl,retrievedAt:item.retrievedAt,method:item.spec.method,observations:item.observations,historyTitle:item.spec.title,historySource:item.spec.source,historyFrequency:item.spec.frequency,sourceId:item.id,historyId:item.id,historyRetrievedAt:item.retrievedAt,flags:[extendedSummary(item).outdated?'Older observation or acquisition':null,extendedSummary(item).laterMissing?'Later supplied period not reported':null].filter(Boolean)});
 }
 const annualGroups={gdp:'Annual context',inflation:'Annual context',unemployment:'Labour and activity',currentAccount:'External accounts',fdi:'External accounts',reserves:'External accounts'};
 const ids=Object.keys(CONTEXT_WDI).map(key=>'wdi-'+country+'-'+key);
 if(country==='USA')ids.push('us-unemployment','us-payrolls','us-production','us-retail','us-claims','us-2y','broad-dollar','fed-assets','treasury-cash','reverse-repo');
 if(country==='IDN')ids.push('id-jisdor');
 for(const id of ids){const item=contextSeries(feed,id),spec=CONTEXT_SERIES[id],summary=contextSummary(item);if(!spec||!item)continue;
  const metric=id.startsWith('wdi-')?id.split('-').at(-1):null,group=metric?annualGroups[metric]:spec.group==='liquidity'?'US liquidity':spec.group==='currency'?'Currency references':spec.group==='rates'?'Policy and yields':'Labour and activity';
  entries.push({id,group,title:spec.title+(spec.frequency==='A'?' (annual)':''),unit:spec.unit,frequency:spec.frequency,latest:summary.available?summary.latest:null,source:spec.source,sourceUrl:spec.sourceUrl,retrievedAt:item.retrievedAt,method:spec.method,observations:item.observations,historyTitle:spec.title,historySource:spec.source,historyFrequency:spec.frequency,sourceId:id,historyId:id,historyRetrievedAt:item.retrievedAt,flags:[item.error,summary.outdated?'Older observation or acquisition':null,summary.laterMissing?'Later supplied period not reported':null].filter(Boolean)});
 }
 return entries;
}
function renderEconomicIndicators(entries,{group,selected,width,range}){
 const visible=entries.filter(e=>e.group===group),item=visible.find(e=>e.id===selected)||visible[0];
 if(!item)return '<p class="quiet-note">No verified indicator connected in this group.</p>';
 const rows=contextWindow(item.observations,range),different=item.sourceId!==item.historyId;
 return `<section class="macro-indicator-explorer" aria-label="Economic data explorer"><div class="indicator-list" role="group" aria-label="Choose an economic indicator">${visible.map(e=>`<button type="button" data-context-data-series="${esc(e.id)}" aria-pressed="${e.id===item.id}"><span>${esc(e.title)}</span><strong>${e.latest?num(e.latest.value):'Not reported'}<small>${esc(e.unit)}</small></strong><small>${e.latest?esc(period({frequency:e.frequency},e.latest))+' · '+cadence[e.frequency]:'No verified numeric observation'}</small></button>`).join('')}</div><div class="indicator-investigation"><header><div><h4>${esc(item.title)}</h4><p>${esc(item.source)} · ${cadence[item.frequency]}</p></div><a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener noreferrer">Official source</a></header>${item.flags.map(flag=>'<p class="macro-warning">'+esc(flag)+'</p>').join('')}${different?'<p class="release-history-boundary">Latest reading and historical chart use separate source series. No values are joined or carried forward.</p>':''}${nativeMacroChart(rows,{width:Math.max(240,width>=900?width-270:width),height:240,title:item.historyTitle,unit:item.unit,frequency:item.historyFrequency,bars:item.historyFrequency==='A'||item.id==='gdp'})}<p class="indicator-history-source">Historical source: ${esc(item.historySource)}. Acquired ${esc(item.historyRetrievedAt?.slice(0,10)||'Not supplied')}. ${rows.length} supplied observations in this window.</p><details class="indicator-method"><summary>Definition and acquisition</summary><p>${esc(item.method)}</p><p>Latest-reading source acquired ${esc(item.retrievedAt)}. Observation dates are not release dates. Original units and frequency are retained.</p></details></div></section><p class="indicator-coverage-note">${entries.filter(e=>e.latest).length} of ${entries.length} connected indicator records have a numeric reading for this economy. Annual context is kept separate from monthly and quarterly releases. This is not full coverage of every economic indicator.</p>`;
}

// Use only additional connected series. Never pad the panel with duplicate GDP/CPI
// readings or substitute another economy when a country has fewer observations.
export function monitorSupportingIndicators(entries,country){
 const ids=country==='USA'?['us-unemployment','us-production','us-retail','us-claims','wdi-USA-currentAccount','broad-dollar']:[...['unemployment','currentAccount','fdi','reserves'].map(key=>'wdi-'+country+'-'+key),...(country==='IDN'?['id-jisdor']:[])];
 return ids.map(id=>entries.find(e=>e.id===id)).filter(e=>e&&Number.isFinite(e.latest?.value)).slice(0,6);
}
function renderMacroMonitor({feed,releases,legacy,extended,country},{width,range,errors=[]}){
 const readings=briefingReadings({context:feed,releases,legacy,extended,country}),cycle=annualCycle(feed,country),rightWidth=width>=950?(width-20)*.56:width;
 const history=r=>{const item=releaseHistory(r.items);if(!item)return '<section class="monitor-history"><h3>'+esc(r.label)+'</h3><p>No verified historical series connected.</p></section>';return `<section class="monitor-history" data-monitor-history="${r.key}"><h3>${r.key==='gdp'?'Real GDP growth':'Consumer price inflation'}</h3>${nativeMacroChart(contextWindow(item.observations,range),{width:Math.max(240,rightWidth-32),height:200,title:item.spec.title,unit:'% YoY',frequency:item.spec.frequency,bars:r.key==='gdp'})}${item.id!==r.item?.id?'<p class="monitor-history-basis">Historical chart uses a separate source series.</p>':''}</section>`;};

 return `<section class="macro-direct-monitor" aria-label="Economic monitor"><header class="monitor-heading"><div><h2>Cycle analysis</h2><p>Quarterly alignment and latest-release comparisons keep distinct reporting periods.</p></div></header>${errors.filter(Boolean).map(e=>'<p class="macro-warning">'+esc(e)+'. Existing verified observations remain available.</p>').join('')}<div class="monitor-analysis-grid"><section class="monitor-cycle" aria-label="Synchronized quarterly cycle">${renderQuarterlyRegime(readings,{country:CONTEXT_COUNTRIES[country]})}</section><section class="monitor-cycle" aria-label="Latest-release cycle">${renderLatestCycle(readings,{country:CONTEXT_COUNTRIES[country],width:Math.max(240,rightWidth-32),quarterReference:false})}</section></div><details class="monitor-source-histories"><summary>GDP & CPI source histories</summary><div class="monitor-history-column">${readings.slice(0,2).map(history).join('')}</div></details><details class="cycle-annual-archive"><summary>Annual cycle archive${cycle.length?" · through "+cycle.at(-1).year:""}</summary>${cycleFigure(cycle,Math.max(240,width-32))}<p class="monitor-source">World Bank annual observations. Separate from the latest-release comparison.</p></details></section>`;
}

export function macroCycleQuad(point){
 if(!point||!Number.isFinite(point.growthChange)||!Number.isFinite(point.inflationChange)||point.growthChange===0||point.inflationChange===0)return null;
 return point.growthChange>0?(point.inflationChange<0?1:2):(point.inflationChange>0?3:4);
}
function cycleFigure(rows,width){
 if(!rows.length)return '<p class="quiet-note">A cycle trajectory needs GDP and inflation for the same consecutive annual periods. No regime is estimated.</p>';
 const points=rows.slice(-12),latest=points.at(-1),quadNames={1:'Growth up, inflation down',2:'Growth up, inflation up',3:'Growth down, inflation up',4:'Growth down, inflation down'},counts=[1,2,3,4].map(quad=>({quad,count:points.filter(p=>macroCycleQuad(p)===quad).length})),maxX=macroScale([-Math.max(1,...points.map(o=>Math.abs(o.growthChange))),Math.max(1,...points.map(o=>Math.abs(o.growthChange)))]).hi,maxY=macroScale([-Math.max(1,...points.map(o=>Math.abs(o.inflationChange))),Math.max(1,...points.map(o=>Math.abs(o.inflationChange)))]).hi;
 const w=Math.max(280,Math.min(760,width>=900?width-250:width)),h=310,l=48,r=w-18,t=32,b=258,x=v=>l+(v+maxX)/2/maxX*(r-l),y=v=>b-(v+maxY)/2/maxY*(b-t),cx=x(0),cy=y(0);
 const quarters=[['Slower growth','Rising inflation',l,t,cx-l,cy-t],['Faster growth','Rising inflation',cx,t,r-cx,cy-t],['Slower growth','Easing inflation',l,cy,cx-l,b-cy],['Faster growth','Easing inflation',cx,cy,r-cx,b-cy]];
 const chartWidth=width>=800?Math.max(240,(width-24)/2):Math.max(240,width);
 const history=(key,title)=>nativeMacroChart(points.map(o=>({date:o.year+'-01-01',value:o[key],status:'derived'})),{width:chartWidth,height:220,title,unit:'percentage points',frequency:'A',bars:true});
 return `<section class="context-cycle-timeline cycle-quadrant-desk" data-cycle-observations="${esc(JSON.stringify(points))}" aria-label="Annual growth and inflation changes"><header><div><h4>Growth and inflation cycle</h4><p>Annual rate changes. One point per year. Units are percentage points.</p></div></header><div class="cycle-quadrant-layout"><figure class="context-cycle"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="Four growth and inflation quadrants. Select a year to inspect its observation.">${quarters.map(([growth,inflation,a,b,c,d],i)=>`<rect data-cycle-zone="${[3,2,4,1][i]}" class="cycle-quadrant-fill q${i} ${macroCycleQuad(latest)===[3,2,4,1][i]?'is-selected-zone':''}" x="${a}" y="${b}" width="${c}" height="${d}"/><text class="cycle-zone-label" x="${a+12}" y="${b+(i<2?18:d-44)}" font-size="11">Quad ${[3,2,4,1][i]}<tspan x="${a+12}" dy="14">${growth}</tspan><tspan x="${a+12}" dy="14">${inflation}</tspan></text>`).join('')}<path class="macro-zero" d="M${cx} ${t}V${b}M${l} ${cy}H${r}"/>${[-maxX,0,maxX].map(v=>`<text x="${x(v)}" y="${b+19}" text-anchor="middle" font-size="11">${num(v)}</text>`).join('')}${[-maxY,0,maxY].map(v=>`<text x="${l-8}" y="${y(v)+4}" text-anchor="end" font-size="11">${num(v)}</text>`).join('')}${points.map((o,i)=>{const prior=points[i-1];return (prior&&Number(o.year)-Number(prior.year)===1?`<path class="cycle-link ${i===points.length-1?'is-current':''}" data-cycle-link="${i}" d="M${x(prior.growthChange)} ${y(prior.inflationChange)}L${x(o.growthChange)} ${y(o.inflationChange)}"/>`:'')+`<circle class="cycle-dot ${i===points.length-1?'is-current':''}" data-cycle-point="${i}" tabindex="0" role="button" aria-pressed="${i===points.length-1}" aria-label="${o.year}, growth change ${num(o.growthChange)}, inflation change ${num(o.inflationChange)} percentage points" cx="${x(o.growthChange)}" cy="${y(o.inflationChange)}" r="${i===points.length-1?5:3.5}"><title>${o.year}</title></circle>`;}).join('')}<text x="${(l+r)/2}" y="301" text-anchor="middle" font-size="11">Growth change (pp)</text><text x="${l}" y="17" font-size="11">Inflation change (pp)</text></svg><figcaption>Right: growth accelerates. Up: inflation rises. Zero means no change in the annual rate.</figcaption></figure><aside class="cycle-inspector" aria-label="Selected annual observation"><label>Observation year<select data-cycle-year>${points.map((o,i)=>`<option value="${i}" ${i===points.length-1?'selected':''}>${o.year}${i===points.length-1?' (latest)':''}</option>`).join('')}</select></label><p class="cycle-quad-badge" data-cycle-quad>${macroCycleQuad(latest)?'Quad '+macroCycleQuad(latest):'On an axis'}</p><p data-cycle-state>${esc(latest.state)}</p><dl><div><dt>Growth change</dt><dd data-cycle-growth>${num(latest.growthChange)} pp</dd></div><div><dt>Inflation change</dt><dd data-cycle-inflation>${num(latest.inflationChange)} pp</dd></div></dl><label class="cycle-path-option"><input type="checkbox" data-cycle-full-path> Show full trajectory</label><p class="quiet-note">The highlighted line joins the selected year to the previous year, when consecutive. Click a point or choose a year.</p></aside></div><div class="cycle-regime-context"><section aria-label="Frequency of observed annual states"><h5>Observed states</h5><p>Last ${points.length} valid annual observations</p><ul>${counts.map(o=>`<li data-cycle-regime="${o.quad}" ${macroCycleQuad(latest)===o.quad?'class="is-current"':''}><strong>Quad ${o.quad}</strong><span>${quadNames[o.quad]}</span><small>${o.count} of ${points.length}</small></li>`).join('')}</ul>${points.some(p=>!macroCycleQuad(p))?'<p>Axis observations remain unclassified.</p>':''}</section><section aria-label="Annual cycle sequence"><h5>The path by year</h5><p>Reported annual changes. No projections.</p><div class="cycle-year-trail">${points.map((o,i)=>`<button type="button" data-cycle-point="${i}" class="cycle-year-chip ${i===points.length-1?'is-current':''}" aria-pressed="${i===points.length-1}" aria-label="Inspect ${o.year}, ${macroCycleQuad(o)?'Quad '+macroCycleQuad(o):'on an axis'}"><span class="cycle-state-dot regime-${macroCycleQuad(o)||'axis'}"></span><strong>${o.year}</strong><small>${macroCycleQuad(o)?'Q'+macroCycleQuad(o):'Axis'}</small></button>`).join('')}</div></section></div><details class="cycle-trajectory-detail"><summary>Changes over time<span>Annual bar charts</span></summary><div class="cycle-time-charts">${history('growthChange','Change in growth')}${history('inflationChange','Change in inflation')}</div></details><details class="cycle-original-observations"><summary>Observations and method</summary><p>Each change is the reported annual rate minus the preceding year's rate. Both series must cover the same two years. Missing years break the path. The last twelve valid annual points are shown. Historical description, not a forecast or allocation signal.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Annual cycle observations"><table><thead><tr><th>Year</th><th>GDP % YoY</th><th>CPI % YoY</th><th>Growth change, pp</th><th>Inflation change, pp</th></tr></thead><tbody>${points.map(o=>`<tr><th scope="row">${o.year}</th><td>${num(o.growth)}</td><td>${num(o.inflation)}</td><td>${num(o.growthChange)}</td><td>${num(o.inflationChange)}</td></tr>`).join('')}</tbody></table></div></details></section>`;
}
function inspectCycle(target){
 const root=target.closest('[data-cycle-observations]');if(!root)return;
 if(target.matches('[data-cycle-full-path]')){root.classList.toggle('show-cycle-path',target.checked);root.closest('#macro-context')._cycleFullPath=target.checked;return;}
 const index=Number(target.matches('[data-cycle-year]')?target.value:target.dataset.cyclePoint),points=JSON.parse(root.dataset.cycleObservations),point=points[index];if(!point)return;root.closest('#macro-context')._cycleYear=point.year;
 root.querySelector('[data-cycle-year]').value=String(index);const quad=macroCycleQuad(point);root.querySelector('[data-cycle-quad]').textContent=quad?'Quad '+quad:'On an axis';root.querySelectorAll('[data-cycle-zone]').forEach(e=>e.classList.toggle('is-selected-zone',Number(e.dataset.cycleZone)===quad));root.querySelectorAll('[data-cycle-regime]').forEach(e=>e.classList.toggle('is-current',Number(e.dataset.cycleRegime)===quad));root.querySelector('[data-cycle-state]').textContent=point.year+' · '+point.state;root.querySelector('[data-cycle-growth]').textContent=num(point.growthChange)+' pp';root.querySelector('[data-cycle-inflation]').textContent=num(point.inflationChange)+' pp';
 root.querySelectorAll('[data-cycle-point]').forEach(e=>{const active=Number(e.dataset.cyclePoint)===index;e.classList.toggle('is-current',active);e.setAttribute('aria-pressed',String(active));if(e.matches('circle'))e.setAttribute('r',active?'5':'3.5');});root.querySelectorAll('[data-cycle-link]').forEach(e=>e.classList.toggle('is-current',Number(e.dataset.cycleLink)===index));
}
if(typeof document!=='undefined'){
document.addEventListener('change',e=>{if(e.target.matches('[data-cycle-year],[data-cycle-full-path]'))inspectCycle(e.target);});
document.addEventListener('click',e=>{const point=e.target.closest?.('[data-cycle-point]');if(point)inspectCycle(point);});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-cycle-point]'))inspectCycle(e.target);});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-cycle-point]')&&['Enter',' '].includes(e.key)){e.preventDefault();inspectCycle(e.target);}});

}



function rateReading(series,spec){const m=contextSummary(series);return `<div class="context-reading"><div><h4>${esc(CONTEXT_COUNTRIES[spec.scope]||spec.scope)}</h4><p>${esc(spec.title)}<br>${esc(spec.source)}</p></div><div><strong>${m.available?num(m.latest.value):series.error?'Source unavailable':'Not reported'}</strong><span>${esc(spec.unit)} · ${esc(period(spec,m.latest))}</span>${m.outdated?'<span class="macro-warning">Older observation or acquisition</span>':''}</div></div>`;}

function indicatorStrip(feed,country,selected){return '<div class="context-indicator-strip" role="group" aria-label="Annual economic indicators">'+Object.entries(CONTEXT_WDI).map(([key,definition])=>{const s=contextSeries(feed,'wdi-'+country+'-'+key),m=contextSummary(s);return `<button type="button" data-context-indicator="${key}" aria-pressed="${key===selected}"><span>${esc(definition[1])}</span><strong>${m.available?num(m.latest.value):'Not reported'}</strong><small>${esc(definition[2])} · ${m.latest?.date.slice(0,4)||'No year'}${m.laterMissing?' · Later year missing':''}${m.outdated?' · Older source':''}</small></button>`;}).join('')+'</div>';}
function countryHistoryBrief(s,spec){const rows=s.observations.filter(o=>Number.isFinite(o.value));if(!rows.length)return '';const first=rows[0],last=rows.at(-1),missing=s.observations.filter(o=>o.date>=first.date&&o.date<=last.date&&!Number.isFinite(o.value)).length;return `<div class="context-history-brief"><div><span>Available source history</span><strong>${first.date.slice(0,4)} to ${last.date.slice(0,4)}</strong><small>${rows.length} reported annual observations${missing?' · '+missing+' unreported years within coverage':''}</small></div><p>${esc(spec.method)} History is the latest published vintage, so past values may be revised. It is separate from the inputs retained in saved research.</p></div>`;}

function metricRow(feed,id){const s=contextSeries(feed,id),spec=CONTEXT_SERIES[id],m=contextSummary(s),change=previousChange(s);return `<tr data-context-series="${id}"><th scope="row">${esc(spec.title)}<small>${cadence[spec.frequency]}</small></th><td><strong>${m.available?num(m.latest.value):s?.error?'Source unavailable':'Not reported'}</strong><small>${esc(spec.unit)}</small></td><td>${esc(period(spec,m.latest))}${s?.error?'<small class="macro-warning">'+esc(s.error)+'</small>':''}${m.outdated?'<small class="macro-warning">Older observation or acquisition</small>':''}${m.laterMissing?'<small>Later supplied year not reported</small>':''}</td><td>${change?(change.value>0?'+':'')+num(change.value)+' '+(spec.unit.startsWith('%')?'pp':spec.unit.includes('100')?'index points':esc(spec.unit))+'<small>vs '+esc(period(spec,{date:change.priorDate}))+'</small>':'Comparison unavailable'}</td></tr>`;}
function observationsTable(feed,ids,title){return `<div class="table-wrap context-ledger" tabindex="0" role="region" aria-label="${esc(title)}"><table><caption>${esc(title)}</caption><thead><tr><th scope="col">Indicator</th><th scope="col">Latest reported</th><th scope="col">Observation period</th><th scope="col">Change from previous observation</th></tr></thead><tbody>${ids.map(id=>metricRow(feed,id)).join('')}</tbody></table></div>`;}
function annualComparison(feed,metric){return `<details class="context-country-comparison"><summary>Compare all ${Object.keys(CONTEXT_COUNTRIES).length} economies</summary><p>Reported annual observations. Years may differ, so this is not a common-period ranking. World and euro area are aggregates. No regional value is assigned to a country.</p><div class="table-wrap" tabindex="0" role="region" aria-label="All economies annual comparison"><table><thead><tr><th>Economy</th><th>${esc(CONTEXT_WDI[metric][1])}</th><th>Year</th><th>Coverage</th></tr></thead><tbody>${Object.entries(CONTEXT_COUNTRIES).map(([id,name])=>{const m=contextSummary(contextSeries(feed,'wdi-'+id+'-'+metric));return `<tr><th scope="row"><button type="button" class="text-button" data-context-country="${id}">${esc(name)}</button></th><td>${m.available?num(m.latest.value)+' '+esc(CONTEXT_WDI[metric][2]):'Not reported'}</td><td>${m.latest?.date.slice(0,4)||'Not reported'}</td><td>${!m.available?'No value supplied':m.outdated?'Older observation or acquisition':m.laterMissing?'Later year not reported':'As published'}</td></tr>`;}).join('')}</tbody></table></div></details>`;}
